css:
.cc-msg, .cc-featured, .cc-alert, .cc-vp, .cc-total {
  box-shadow: 0 0 0 1.5px var(--cc-p), 0 0 16px color-mix(in srgb, var(--cc-p) 55%, transparent), inset 0 0 18px color-mix(in srgb, var(--cc-p) 16%, transparent);
}
.cc-name { text-shadow: 0 0 10px var(--cc-name); }
.cc-icon { filter: drop-shadow(0 0 6px var(--cc-p)); }
